package com.marketplace.adapters.out.persistence.party;
import com.marketplace.domain.party.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class JpaPartyRepositoryAdapter implements PartyRepository { private final SpringDataPartyRepository repo; public JpaPartyRepositoryAdapter(SpringDataPartyRepository repo){this.repo=repo;} public Party save(Party p){return domain(repo.save(entity(p)));} public Optional<Party> findByIdAndType(Long id,PartyType t){return repo.findByIdAndType(id,t).map(JpaPartyRepositoryAdapter::domain);} public List<Party> findActiveByType(PartyType t){return repo.findByTypeAndActiveTrueOrderByNameAsc(t).stream().map(JpaPartyRepositoryAdapter::domain).toList();} private static PartyJpaEntity entity(Party p){var e=new PartyJpaEntity();e.id=p.id();e.type=p.type();e.name=p.name();e.email=p.email();e.document=p.document();e.active=p.active();e.createdAt=p.createdAt();return e;} private static Party domain(PartyJpaEntity e){return Party.restore(e.id,e.type,e.name,e.email,e.document,e.active,e.createdAt);} }
